import{_ as e,o as a,c as d,a2 as s}from"./chunks/framework.BM5YPQmL.js";const m=JSON.parse('{"title":"User manual","description":"","frontmatter":{},"headers":[],"relativePath":"manual/index.md","filePath":"manual/index.md"}'),o={name:"manual/index.md"};function r(n,t,i,l,c,h){return a(),d("div",null,[...t[0]||(t[0]=[s(`<h1 id="user-manual" tabindex="-1">User manual <a class="header-anchor" href="#user-manual" aria-label="Permalink to &quot;User manual&quot;">​</a></h1><p>Everything an operator needs to run Open Cube OS 3.0.0.</p><p>The command surface is organized around <strong>eight merged apps</strong> - <code>update</code>, <code>disk-tool</code>, <code>net-tool</code>, <code>sound-tool</code>, <code>files</code>, <code>sysdiag</code>, <code>hwinfo</code>, <code>power</code>. Each one is an intent wizard <em>and</em> a verbatim dispatch for every historical command underneath it. The 284-entry program registry keeps all the classic single commands available byte-for-byte.</p><table tabindex="0"><thead><tr><th>Page</th><th>What it covers</th></tr></thead><tbody><tr><td><a href="./getting-started.html">getting-started</a></td><td>download, boot in QEMU, the first five minutes</td></tr><tr><td><a href="./mega-apps.html">mega-apps</a></td><td>the 8 merged apps: wizard / direct / classic contract</td></tr><tr><td><a href="./shell-basics.html">shell-basics</a></td><td>ush: pipes, redirection, env, aliases, scripting</td></tr><tr><td><a href="./filesystems.html">filesystems</a></td><td>VFS types, formatting, mounting, the /etc volume</td></tr><tr><td><a href="./network.html">network</a></td><td>address setup, WiFi/Bluetooth, firewall, TLS + SSH</td></tr><tr><td><a href="./update-ota.html">update-ota</a></td><td>the 5-step update wizard, install, rollback</td></tr><tr><td><a href="./boot-modes.html">boot-modes</a></td><td>BIOS + UEFI, the GRUB A/B slot menu, persistence</td></tr><tr><td><a href="./tui-guide.html">tui-guide</a></td><td>the desktop, apps, keyboard model</td></tr><tr><td><a href="./chinese-console.html">chinese-console</a></td><td>the CN layer, IME, the ASCII contract</td></tr><tr><td><a href="./recovery.html">recovery</a></td><td>the WinRE workflow, crash artifacts, rescue kit</td></tr><tr><td><a href="./commands/">commands</a></td><td>ALL 284 command reference pages (every command home: L0, SVC, built-ins)</td></tr></tbody></table><h2 id="the-8-merged-apps-at-a-glance" tabindex="-1">The 8 merged apps at a glance <a class="header-anchor" href="#the-8-merged-apps-at-a-glance" aria-label="Permalink to &quot;The 8 merged apps at a glance&quot;">​</a></h2><table tabindex="0"><thead><tr><th>App</th><th>Intent</th><th>Classic ops it wraps</th></tr></thead><tbody><tr><td><code>update</code></td><td>bring the machine to the newest version</td><td>the OTA chain: status, checkupdate, install, rollback</td></tr><tr><td><code>disk-tool</code></td><td>disks, partitions, filesystems</td><td>lsblk, parted, mkfs.*, mount family, fsck, A/B tools</td></tr><tr><td><code>net-tool</code></td><td>connectivity and address management</td><td>ip, dhcp, dns, route, arp, firewall, wifi, bt, ssh</td></tr><tr><td><code>sound-tool</code></td><td>audio devices and playback</td><td>sound, volume, play, per-driver status + selftests</td></tr><tr><td><code>files</code></td><td>day-to-day file work</td><td>ls, tree, df, du, cp, mv, rm, edit, stat, chmod</td></tr><tr><td><code>sysdiag</code></td><td>&quot;something feels wrong - look&quot;</td><td>health, dmesg, memory/scheduler stats, selftests</td></tr><tr><td><code>hwinfo</code></td><td>what hardware is in this machine</td><td>uname, clocks, PCI, ACPI, SMBus, USB, cameras</td></tr><tr><td><code>power</code></td><td>shutdown / reboot / halt / sleep</td><td>the power ops plus their path selftests</td></tr></tbody></table><p>Every app follows the same three-door contract:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ush&gt; &lt;app&gt;              the intent wizard (menus, checks, confirmations)</span></span>
<span class="line"><span>ush&gt; &lt;app&gt; direct &lt;op&gt;  explicit verbatim passthrough of one op</span></span>
<span class="line"><span>ush&gt; &lt;app&gt; &lt;op&gt; [args]  classic dispatch - identical to the historical command</span></span></code></pre></div><p>Details and per-app walkthroughs: <a href="./mega-apps.html">mega-apps</a>.</p>`,9)])])}const u=e(o,[["render",r]]);export{m as __pageData,u as default};
